namespace sv_3a39fdd263494f03b1feb435f8fe1195.Services;

public class MockChatService : IChatService
{
    private readonly List<Channel> _channels = new()
    {
        new(1, "general", "General discussion for the team", 3),
        new(2, "engineering", "Engineering topics and code reviews", 0),
        new(3, "design", "Design feedback and assets", 1),
        new(4, "random", "Off-topic fun and memes", 5),
        new(5, "announcements", "Important team announcements", 0)
    };

    private readonly List<Message> _messages = new()
    {
        new(1, 1, "Alice", "Hey team! How's everyone doing today?", DateTime.Now.AddHours(-2), null, new() { new("👋", new() { "Bob", "Carol" }) }),
        new(2, 1, "Bob", "Doing great! Just finished the sprint review.", DateTime.Now.AddHours(-1.5), null, new() { new("🎉", new() { "Alice" }) }),
        new(3, 1, "Carol", "Nice work Bob! I have some questions about the API changes.", DateTime.Now.AddMinutes(-45), 2, new()),
        new(4, 1, "Alice", "Let's discuss in the thread. I had similar questions.", DateTime.Now.AddMinutes(-30), 2, new()),
        new(5, 1, "Dave", "Anyone up for lunch?", DateTime.Now.AddMinutes(-10), null, new() { new("🍕", new() { "Alice", "Bob", "Carol" }), new("👍", new() { "Eve" }) }),
        new(6, 2, "Eve", "PR #142 is ready for review. It refactors the auth module.", DateTime.Now.AddHours(-3), null, new() { new("👀", new() { "Alice" }) }),
        new(7, 2, "Alice", "I'll take a look this afternoon.", DateTime.Now.AddHours(-2.5), null, new()),
        new(8, 3, "Carol", "New mockups for the dashboard are in Figma.", DateTime.Now.AddHours(-4), null, new() { new("🎨", new() { "Dave", "Eve" }) }),
    };

    public Task<List<Channel>> GetChannelsAsync() => Task.FromResult(_channels.ToList());

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take)
    {
        var result = _messages
            .Where(m => m.ChannelId == channelId && m.ReplyToId == null)
            .OrderByDescending(m => m.SentAt)
            .Skip(skip)
            .Take(take)
            .OrderBy(m => m.SentAt)
            .ToList();
        return Task.FromResult(result);
    }

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var id = _messages.Count > 0 ? _messages.Max(m => m.Id) + 1 : 1;
        var message = new Message(id, channelId, "You", content, DateTime.Now, replyToId, new());
        _messages.Add(message);
        return Task.FromResult(message);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId)
    {
        var replies = _messages
            .Where(m => m.ReplyToId == rootMessageId)
            .OrderBy(m => m.SentAt)
            .ToList();
        return Task.FromResult(replies);
    }

    public Task AddReactionAsync(int messageId, string emoji)
    {
        var msg = _messages.FirstOrDefault(m => m.Id == messageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing is not null)
            {
                existing.Users.Add("You");
            }
            else
            {
                msg.Reactions.Add(new Reaction(emoji, new() { "You" }));
            }
        }
        return Task.CompletedTask;
    }

    public Task MarkChannelReadAsync(int channelId)
    {
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            _channels[idx] = _channels[idx] with { UnreadCount = 0 };
        }
        return Task.CompletedTask;
    }
}

