@rendermode InteractiveServer
@using sv_3a39fdd263494f03b1feb435f8fe1195.Models
@using sv_3a39fdd263494f03b1feb435f8fe1195.Services
@using sv_3a39fdd263494f03b1feb435f8fe1195.Components.Chat
@inject IChatService ChatService

<PageTitle>Team Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="Channels"
                    ActiveChannelId="_activeChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="chat-main @(ThreadOpen ? "thread-open" : "")">
        <MessageArea ChannelName="@ActiveChannel?.Name"
                     Description="@ActiveChannel?.Description"
                     Messages="Messages"
                     ThreadReplyCounts="ThreadReplyCounts"
                     IsLoading="_isLoadingMessages"
                     OnLoadMore="LoadOlderMessages"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnSendMessage="SendMessage" />
    </div>

    @if (ThreadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="ThreadReplies"
                     OnClose="CloseThread"
                     OnReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> Channels { get; set; } = new();
    private List<Message> Messages { get; set; } = new();
    private List<Message> ThreadReplies { get; set; } = new();
    private Dictionary<int, int> ThreadReplyCounts { get; set; } = new();

    private int _activeChannelId;
    private Message? _threadRootMessage;
    private bool _isLoadingMessages;
    private int _messageSkip;
    private const int PageSize = 50;

    private Channel? ActiveChannel => Channels.FirstOrDefault(c => c.Id == _activeChannelId);
    private bool ThreadOpen => _threadRootMessage is not null;

    protected override async Task OnInitializedAsync()
    {
        Channels = await ChatService.GetChannelsAsync();
        if (Channels.Count > 0)
        {
            await SelectChannel(Channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _activeChannelId = channelId;
        _messageSkip = 0;
        Messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channelId);
        Channels = await ChatService.GetChannelsAsync();
        await ComputeThreadCounts();
        CloseThreadSync();
    }

    private async Task LoadOlderMessages()
    {
        if (_isLoadingMessages) return;
        _isLoadingMessages = true;
        _messageSkip += PageSize;
        var older = await ChatService.GetMessagesAsync(_activeChannelId, _messageSkip, PageSize);
        if (older.Count > 0)
        {
            Messages = older.Concat(Messages).ToList();
        }
        _isLoadingMessages = false;
    }

    private async Task SendMessage(string content)
    {
        var message = await ChatService.SendMessageAsync(_activeChannelId, content, null);
        Messages.Add(message);
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = Messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is not null)
        {
            ThreadReplies = await ChatService.GetThreadAsync(messageId);
        }
    }

    private void CloseThreadSync()
    {
        _threadRootMessage = null;
        ThreadReplies = new();
    }

    private async Task CloseThread()
    {
        CloseThreadSync();
        await Task.CompletedTask;
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_activeChannelId, content, _threadRootMessage.Id);
        ThreadReplies.Add(reply);
        await ComputeThreadCounts();
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        // Refresh messages to show updated reactions
        Messages = await ChatService.GetMessagesAsync(_activeChannelId, 0, _messageSkip + PageSize);
    }

    private async Task ComputeThreadCounts()
    {
        ThreadReplyCounts = new();
        foreach (var msg in Messages)
        {
            var replies = await ChatService.GetThreadAsync(msg.Id);
            if (replies.Count > 0)
            {
                ThreadReplyCounts[msg.Id] = replies.Count;
            }
        }
    }
}
