    padding-bottom: 12px;
}

.channel-list {
    overflow-y: auto;
    flex: 1;
    padding: 8px 0;
}

.channel-item {
    padding: 8px 16px;
    cursor: pointer;
    position: relative;
    transition: background 0.15s;
}

.channel-item:hover {
    background: #2d3039;
}

.channel-item.active {
    background: #3b4048;
    border-left: 3px solid #4a9eff;
}

.channel-name {
    font-weight: 600;
    font-size: 0.9rem;
    color: #e0e0e0;
}

.channel-description {
    font-size: 0.75rem;
    color: #888;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    margin-top: 2px;
}

.unread-badge {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: #4a9eff;
    color: #fff;
    border-radius: 10px;
    padding: 2px 7px;
    font-size: 0.7rem;
    font-weight: 700;
}

/* Main Message Area */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main.thread-open {
    width: 55%;
    flex: none;
}

.message-area {
    display: flex;
    flex-direction: column;
    flex: 1;
    background: #fff;
}

.message-header-bar {
    padding: 12px 20px;
    border-bottom: 1px solid #e5e5e5;
    background: #fafafa;
}

.channel-title {
    margin: 0;
    font-size: 1.1rem;
    color: #1a1a1a;
}

.channel-desc {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #666;
}

/* Message List */
.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px 20px;
}

.loading-indicator {
    text-align: center;
    color: #888;
    padding: 12px;
    font-size: 0.85rem;
}

/* Message Bubble */
.message-bubble {
    padding: 8px 12px;
    margin-bottom: 4px;
    border-radius: 6px;
    position: relative;
    transition: background 0.15s;
}

.message-bubble:hover {
    background: #f5f5f5;
}

.message-bubble .message-header {
    display: flex;
    align-items: baseline;
    gap: 8px;
}

.message-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #1a1a1a;
}

.message-time {
    font-size: 0.75rem;
    color: #999;
}

.message-content {
    margin-top: 4px;
    font-size: 0.9rem;
    color: #333;
    line-height: 1.4;
}

/* Reactions */
.message-reactions {
    display: flex;
    gap: 6px;
    margin-top: 6px;
    flex-wrap: wrap;
}

.reaction-badge {
    background: #eef3ff;
    border: 1px solid #d0dfff;
    border-radius: 12px;
    padding: 2px 8px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #d0dfff;
}

